namespace Scada.Api.Runtime;

public static partial class ContextualHelpCatalog
{
    private static IEnumerable<ContextualHelpTopic> BuildObjectWorkflowGuides(string locale)
    {
        yield return LT(locale, "visual.trend-series", "visual",
            Tx("Tendência: configurar cada série e sua escala", "Trend: configure each series and its scale", "Tendencia: configurar cada serie y su escala"),
            Tx("Uma pena é uma curva do gráfico. Escolha seu TAG, identificação e escala para comparar sem confundir grandezas.", "A pen is one chart curve. Set its TAG, identification and scale so quantities can be compared without confusion.", "Una pluma es una curva del gráfico. Defina TAG, identificación y escala para comparar sin confundir magnitudes."),
            [
                LS(locale, "Primeiro escolha o período e as grandezas", "First choose period and quantities", "Primero elija período y magnitudes",
                    "Use um Trend com identidade salva para editar suas penas. Para pressão em bar e corrente em A, duas curvas podem compartilhar o tempo mas precisam de escalas adequadas; não interprete alturas iguais como valores físicos iguais. Configure captura Historian para histórico e confira o período com dados disponíveis.",
                    "Use a Trend with saved identity to edit pens. Pressure in bar and current in A can share time but need suitable scales; equal heights do not mean equal physical values. Configure Historian capture for history and check a period with available data.",
                    "Use un Trend con identidad guardada para editar plumas. Presión en bar y corriente en A comparten tiempo, pero requieren escalas adecuadas; alturas iguales no significan valores físicos iguales. Configure captura Historian y compruebe un período con datos."),
                new ContextualHelpSection(Pick(locale, "Campos de cada pena", "Fields of each pen", "Campos de cada pluma"), Pick(locale,
                    "Adicione uma pena por TAG que deseja acompanhar e ajuste estes campos. A legenda permite ocultar uma série temporariamente no Runtime sem remover sua configuração.",
                    "Add a pen per TAG you want to follow and set these fields. The Runtime legend can temporarily hide a series without removing its configuration.",
                    "Añada una pluma por TAG y ajuste estos campos. La leyenda permite ocultar temporalmente una serie en Runtime sin eliminar la configuración."), Fields:
                [
                    IF(locale, "pens.tag", "TAG", "TAG", "TAG", "Origem dos valores. Use o seletor e confira caminho e unidade do TAG existente.", "Value source. Use the picker and check the existing TAG's path and unit.", "Origen de valores. Use el selector y compruebe ruta y unidad del TAG.", "Pressão de descarga", "Discharge pressure", "Presión de descarga"),
                    IF(locale, "pens.label", "Rótulo", "Label", "Etiqueta", "Nome da curva na legenda; descreva o ponto de medição, não apenas o número da pena.", "Legend curve name; describe the measurement point, not only its pen number.", "Nombre de curva en leyenda; describa el punto, no solo su número.", "Pressão B1", "P1 pressure", "Presión B1"),
                    IF(locale, "pens.unit", "Unidade", "Unit", "Unidad", "Rótulo de unidade da série. Não converte a leitura; deve corresponder à grandeza.", "Series unit label. It does not convert the reading and must match its quantity.", "Etiqueta de unidad. No convierte la lectura y debe coincidir con su magnitud.", "bar", "bar", "bar"),
                    IF(locale, "pens.visible", "Visível", "Visible", "Visible", "Define se a curva aparece inicialmente. O operador pode alternar a visibilidade pela legenda.", "Sets initial curve visibility. The operator can toggle it in the legend.", "Define visibilidad inicial. El operador puede alternarla en la leyenda.", "Sim", "Yes", "Sí"),
                    IF(locale, "pens.appearance", "Cor, espessura e estilo", "Color, width and style", "Color, grosor y estilo", "Distingue as curvas. A espessura aceita 1 a 12; o estilo pode ser contínuo, tracejado ou pontilhado. Evite depender só de cor.", "Distinguishes curves. Width accepts 1–12; style can be solid, dashed or dotted. Do not rely on color alone.", "Distingue curvas. Grosor de 1 a 12; estilo continuo, discontinuo o punteado. No dependa solo del color.", "Azul, 2, contínua", "Blue, 2, solid", "Azul, 2, continua"),
                    IF(locale, "pens.axis", "Eixo", "Axis", "Eje", "Escolhe a escala esquerda ou direita. Penas no mesmo eixo compartilham a escala; reúna apenas grandezas compatíveis.", "Chooses left or right scale. Pens on the same axis share its scale; group compatible quantities.", "Elige escala izquierda o derecha. Plumas del mismo eje comparten escala; agrupe magnitudes compatibles.", "Pressão à esquerda; corrente à direita", "Pressure left; current right", "Presión izquierda; corriente derecha"),
                    IF(locale, "pens.scale", "Escala, mínimo e máximo", "Scale, minimum and maximum", "Escala, mínimo y máximo", "Automática ajusta a apresentação aos dados; Fixa usa os limites informados. Para comparar períodos visualmente, uma escala fixa coerente evita que a ampliação dê impressão de mudança de amplitude.", "Auto fits the display to data; Fixed uses entered bounds. For visual comparison across periods, a suitable fixed scale avoids misleading amplitude changes caused by zoom.", "Automática adapta a datos; Fija usa límites indicados. Al comparar períodos, una escala fija adecuada evita cambios aparentes de amplitud por ampliación.", "Fixa: 0–10 bar", "Fixed: 0–10 bar", "Fija: 0–10 bar")
                ]),
                LS(locale, "Se a curva não aparecer", "If the curve does not appear", "Si la curva no aparece",
                    "Confira Visível e a legenda, o TAG escolhido, modo ao vivo/histórico, período e captura. Uma escala fixa que não contém os valores pode esconder a curva. A janela e o intervalo de atualização são propriedades do gráfico inteiro, explicadas no tópico do objeto; não substituem a configuração de cada pena.",
                    "Check Visible and legend, selected TAG, live/history mode, period and capture. A fixed scale excluding values can hide the curve. Window and refresh interval belong to the whole chart and are explained in its object topic; they do not replace each pen's configuration.",
                    "Compruebe Visibilidad y leyenda, TAG, modo en vivo/histórico, período y captura. Una escala fija fuera de valores puede ocultar la curva. Ventana y actualización pertenecen al gráfico completo y se explican en su tema; no sustituyen configurar cada pluma.")
            ], "visual.object.core.trend", "historian.overview", "trends.overview");

        yield return LT(locale, "visual.browser-filters", "visual",
            Tx("Navegadores de alarme/evento: campos e filtros", "Alarm/event browsers: fields and filters", "Navegadores de alarma/evento: campos y filtros"),
            Tx("Defina quais registros aparecem, como são ordenados e quais ações o operador pode solicitar.", "Set which records appear, their ordering and the actions an operator can request.", "Defina registros mostrados, ordenación y acciones que puede solicitar el operador."),
            [
                LS(locale, "Comece com poucos filtros", "Start with few filters", "Empiece con pocos filtros",
                    "O navegador de alarmes mostra condições e estado de reconhecimento; o de eventos mostra ocorrências registradas. Primeiro confirme uma consulta sem filtros restritivos. Depois adicione um filtro por vez. Nenhuma linha pode significar período errado ou filtro incompatível, e não necessariamente ausência de ocorrências.",
                    "The alarm browser shows conditions and acknowledgement state; the event browser shows recorded occurrences. First confirm a query without restrictive filters, then add one at a time. No rows may mean a wrong period or incompatible filter rather than no occurrences.",
                    "El navegador de alarmas muestra condiciones y reconocimiento; el de eventos muestra ocurrencias registradas. Confirme primero una consulta poco restringida y añada filtros uno por uno. Sin filas puede significar período o filtro incorrecto, no necesariamente ausencia de eventos."),
                new ContextualHelpSection(Pick(locale, "Configuração de consulta", "Query configuration", "Configuración de consulta"), Pick(locale,
                    "O editor mostra os campos aplicáveis ao tipo de navegador selecionado. Filtros trabalham sobre os metadados registrados; não alteram as definições do alarme ou evento.",
                    "The editor shows fields applicable to the selected browser. Filters act on recorded metadata and do not change alarm/event definitions.",
                    "El editor muestra campos aplicables al navegador seleccionado. Los filtros actúan sobre metadatos registrados y no cambian definiciones."), Fields:
                [
                    IF(locale, "browser.mode", "Fonte de alarmes", "Alarm source", "Fuente de alarmas", "Alarmes atuais apresenta o estado corrente; Histórico consulta transições armazenadas. O campo pertence ao navegador de alarmes.", "Current alarms shows present state; History queries stored transitions. This field belongs to the alarm browser.", "Alarmas actuales muestra estado presente; Histórico consulta transiciones guardadas. Es del navegador de alarmas.", "Histórico de alarmes", "Alarm history", "Historial de alarmas"),
                    IF(locale, "browser.state", "Estado e reconhecimento", "State and acknowledgement", "Estado y reconocimiento", "Filtra Ativos/Retornados e Reconhecidos/Não reconhecidos. Retornado e reconhecido são aspectos diferentes; voltar ao normal não significa que um operador reconheceu.", "Filters Active/Returned and Acknowledged/Unacknowledged. Return and acknowledgement differ; returning to normal does not mean an operator acknowledged it.", "Filtra Activos/Retornados y Reconocidos/No reconocidos. Retorno y reconocimiento difieren; volver a normal no implica reconocimiento.", "Ativos + Não reconhecidos", "Active + Unacknowledged", "Activos + No reconocidos"),
                    IF(locale, "browser.priority", "Severidade mínima", "Minimum severity", "Severidad mínima", "Restringe a consulta pela severidade configurada. Confira a convenção de prioridades da aplicação antes de selecionar 1 a 4.", "Restricts records by configured severity. Check the application's priority convention before selecting 1–4.", "Restringe por severidad configurada. Compruebe la convención de la aplicación antes de elegir 1 a 4.", "Qualquer severidade", "Any severity", "Cualquier severidad"),
                    IF(locale, "browser.filters", "Área, caminho TAG e texto", "Area, TAG path and text", "Área, ruta TAG y texto", "Limitam os registros à origem procurada. Use os mesmos dados cadastrados na aplicação; retire um campo por vez se o resultado ficar vazio.", "Restrict records to the source you seek. Use application metadata and remove one field at a time if results become empty.", "Limitan registros al origen buscado. Use metadatos de la aplicación y quite un campo cada vez si queda vacío.", "Área Bombeamento", "Pumping area", "Área Bombeo"),
                    IF(locale, "browser.eventFields", "Tipo, categoria, origem e equipamento", "Type, category, source and Equipment", "Tipo, categoría, origen y equipo", "No navegador de eventos, selecionam o tipo de ocorrência e sua origem. Operador, operação e comando ajudam a localizar ações quando esses metadados estão presentes.", "In the event browser, select occurrence kind and source. Operator, operation and command help locate actions when those metadata are present.", "En eventos seleccionan clase y origen. Operador, operación y comando ayudan a localizar acciones si esos metadatos existen.", "Tipo e origem da definição real", "Actual definition type and source", "Tipo y origen de definición real"),
                    IF(locale, "browser.lookback", "Janela histórica", "Historical window", "Ventana histórica", "Quantidade de segundos anteriores consultados no modo histórico. 3600 é uma hora; o editor admite 60 a 2678400 segundos. Não cria registros que não foram capturados.", "Seconds of prior history queried. 3600 is one hour; the editor allows 60–2678400 seconds. It does not create uncaptured records.", "Segundos anteriores consultados. 3600 es una hora; se admiten 60–2678400 segundos. No crea registros no capturados.", "3600 s", "3600 s", "3600 s"),
                    IF(locale, "browser.presentation", "Linhas por página, colunas e ordenação", "Rows per page, columns and sorting", "Filas por página, columnas y ordenación", "Escolha 10 a 200 linhas por página, as colunas úteis e o campo/sentido de ordenação. Alterar a página não muda o período consultado.", "Choose 10–200 rows per page, useful columns and sort field/direction. Changing page does not change the query period.", "Elija 10–200 filas, columnas útiles y campo/sentido de orden. Cambiar página no cambia el período.", "50 linhas; horário decrescente", "50 rows; descending time", "50 filas; hora descendente"),
                    IF(locale, "browser.ack", "Permitir ação ACK", "Allow ACK action", "Permitir acción ACK", "Disponibiliza a ação de reconhecimento no objeto. O servidor ainda exige permissão; marcar esta opção não concede autorização ao usuário.", "Makes acknowledgement available in the object. The server still requires permission; selecting this does not grant user authorization.", "Dispone reconocimiento en el objeto. El servidor exige permiso; marcarlo no concede autorización.", "Ativar só onde fizer sentido operacional", "Enable where operationally appropriate", "Habilitar donde sea apropiado")
                ])
            ], "visual.object.core.alarmbrowser", "visual.object.core.eventbrowser", "alarms.overview", "operational-events.overview", "audit.overview");
    }
}
